def push_update(self, device):
    if not self.rate.allow(device.id):
        return self.rate.wait_ms(device.id)
    token = self.auth.token(device.id)
    if token.expired:
        token = self.auth.refresh(device.id)
    payload = self.codec.compress(self.snapshot(device.id))
    self.hb.note('push', {'device': device.id, 'bytes': len(payload)})
    # --- cut: rate/auth above, codec/heartbeat below ---
    return self.transport.push(device.id, payload)

def show_form(self, request):
    errors = self.validator.run(request.form)
    if errors:
        self.flash.store(request.session.id, errors)
    flag = self.flags.enabled('beta_ui') and request.browser.mobile
    self.history.push(request.session.id, request.path)
    self.analytics.track('view', {'form': request.path, 'mobile': flag})
    # --- cut: validation/flash above, history/analytics below ---
    return self.template.render(request.path, errors=errors, beta=flag)

def process_order(self, order):
    if not self.inventory.hold(order.sku, order.qty):
        return 'out_of_stock'
    discount = self.promo.rate(order.code, order.total)
    total = order.total * (1 - discount) + self.tax.apply(order.total)
    body = self.mailer.render('receipt', {'total': total, 'items': order.items})
    self.audit.write(order.id, f'total={total}')
    # --- cut: inventory/pricing above, mail/audit below ---
    return self.mailer.send(order.email, body)

def process_order(order):
    retries = 0
    cache = {}
    while retries < 2:
        try:
            raw = fetch(order['id'])
            if raw['etag'] in cache:
                return order['id'] + ' cached'
            cache[raw['etag']] = raw
            metrics.orders += 1
            write_audit(raw, retries)
            return raw
        except NetworkError:
            retries += 1
